    // ErrorHandling defines how [FlagSet.Parse] behaves if the parse fails.
    // A FlagSet represents a set of defined flags. The zero value of a FlagSet
    // has no name and has [ContinueOnError] error handling.
    //
    // [Flag] names must be unique within a FlagSet. An attempt to define a flag whose
    // name is already in use will cause a panic.
    
    template<typename T> requires gocpp::GoStruct<T>
    FlagSet::operator T()
    {
        T result;
        result.Usage = this->Usage;
        result.name = this->name;
        result.parsed = this->parsed;
        result.actual = this->actual;
        result.formal = this->formal;
        result.args = this->args;
        result.errorHandling = this->errorHandling;
        result.output = this->output;
        result.undef = this->undef;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool FlagSet::operator==(const T& ref) const
    {
        if (Usage != ref.Usage) return false;
        if (name != ref.name) return false;
        if (parsed != ref.parsed) return false;
        if (actual != ref.actual) return false;
        if (formal != ref.formal) return false;
        if (args != ref.args) return false;
        if (errorHandling != ref.errorHandling) return false;
        if (output != ref.output) return false;
        if (undef != ref.undef) return false;
        return true;
    }

