    // sortFlags returns the flags as a slice in lexicographical sorted order.
    gocpp::slice<Flag*> sortFlags(gocpp::map<gocpp::string, Flag*> flags)
    {
        auto result = gocpp::make(gocpp::Tag<gocpp::slice<Flag*>>(), len(flags));
        int64_t i = 0;
        for(auto [gocpp_ignored, f] : flags)
        {
            result[i] = f;
            i++;
        }
        slices::SortFunc(result, [=](Flag* a, Flag* b) mutable -> int64_t
        {
            return strings::Compare(a->Name, b->Name);
        });
        return result;
    }

