    // Set sets the value of the named flag.
    gocpp::error rec::Set(FlagSet* f, gocpp::string name, gocpp::string value)
    {
        return rec::set(gocpp::recv(f), name, value);
    }

    gocpp::error rec::set(FlagSet* f, gocpp::string name, gocpp::string value)
    {
        auto [flag, ok] = f->formal.lookup(name);
        if(! ok)
        {
            // Remember that a flag that isn't defined is being set.
            // We return an error in this case, but in addition if
            // subsequently that flag is defined, we want to panic
            // at the definition point.
            // This is a problem which occurs if both the definition
            // and the Set call are in init code and for whatever
            // reason the init code changes evaluation order.
            // See issue 57411.
            auto [gocpp_id_0, file, line, ok] = runtime::Caller(2);
            if(! ok)
            {
                file = "?"_s;
                line = 0;
            }
            if(f->undef == nullptr)
            {
                f->undef = gocpp::map<gocpp::string, gocpp::string> {gocpp::non_nil};
            }
            f->undef.ref(name) = mocklib::Sprintf("%s:%d"_s, file, line);

            return mocklib::Errorf("no such flag -%v"_s, name);
        }
        auto err = rec::Set(gocpp::recv(flag->Value), value);
        if(err != nullptr)
        {
            return err;
        }
        if(f->actual == nullptr)
        {
            f->actual = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, Flag*>>());
        }
        f->actual.ref(name) = flag;
        return nullptr;
    }

    // Set sets the value of the named command-line flag.
